CREATE TABLE `user_session_contexts` (`session_id` CHAR(36) CHARACTER SET ascii NOT NULL,`user_id` CHAR(36) CHARACTER SET ascii NOT NULL,`organization_id` CHAR(36) CHARACTER SET ascii NOT NULL,`workspace_id` CHAR(36) CHARACTER SET ascii NOT NULL,`selected_at` DATETIME(3) NOT NULL,PRIMARY KEY(`session_id`),KEY `idx_session_context_scope`(`organization_id`,`workspace_id`,`user_id`),CONSTRAINT `fk_context_session` FOREIGN KEY(`session_id`) REFERENCES `user_sessions`(`id`) ON DELETE RESTRICT,CONSTRAINT `fk_context_user` FOREIGN KEY(`user_id`) REFERENCES `users`(`id`) ON DELETE RESTRICT,CONSTRAINT `fk_context_org` FOREIGN KEY(`organization_id`) REFERENCES `organizations`(`id`) ON DELETE RESTRICT,CONSTRAINT `fk_context_workspace` FOREIGN KEY(`workspace_id`) REFERENCES `workspaces`(`id`) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
